from decimal import Decimal, ROUND_HALF_UP
from typing import Any


_CENTS = Decimal("0.01")
_ZERO = Decimal("0")


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric(value: Any) -> Decimal:
    """Apply legacy empty/null-to-zero numeric coercion."""
    if value is None or value == "":
        return _ZERO
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """Apply the invoiced-order status rule and the I-to-X workflow actions."""
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    result = dict(order)

    if new_status == "I":
        return result, [], []

    if new_status == "X":
        result["STAT_CD"] = "X"
        return result, ["ORD_CANC_INV"], ["credit_note"]

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """Recompute live line extensions and the discounted order total."""
    result_order = dict(order)
    result_lines = [dict(line) for line in lines]

    if result_order.get("STAT_CD") in ("I", "X"):
        return result_order, result_lines, []

    total = _ZERO

    for line in result_lines:
        if line.get("DEL_FLG", "") == "Y":
            continue

        extended = _round_cents(
            _numeric(line.get("QTY")) * _numeric(line.get("UNIT_PRC"))
        )
        line["EXT_AMT"] = float(extended)
        total += extended

    discount_percent = _numeric(result_order.get("DISC_PCT"))
    discounted_total = _round_cents(
        total * (Decimal("100") - discount_percent) / Decimal("100")
    )

    changed = _numeric(result_order.get("TOT_AMT")) != discounted_total
    result_order["TOT_AMT"] = float(discounted_total)

    audits = ["ORD_RETOTAL"] if changed else []
    return result_order, result_lines, audits
